  loaders: {
    xgf: new XGFLoader(),
    datamodel: new DataModelParamsLoader()
  },
  exporters: {
    dotbim: new DotBIMExporter()
  },
  pipelines: {
    xgf2dotbim: {
      inputs: {
        xgf: {
          loader: "xgf",
          sceneModel: "mySceneModel",
          options: {}
        },
        datamodel: {
          loader: "datamodel",
          dataModel: "myDataModel",
          options: {}
        }
      },
      outputs: {
        dotbim: {
          exporter: "dotbim",
          sceneModel: "mySceneModel",
          dataModel: "myDataModel",
          version: "1.1",
          options: {}
        }
      }
    }
  }
});
